local config = {
  ui_story_30850101_1_dialog_content = "Urutkan berdasarkan waktu terlebih dahulu, lalu berdasarkan Faction.",
  ui_story_30850101_2_dialog_content = "Berkas Istvan Gang harus ditempatkan di atas intel perdagangan Cloudrover Guild...",
  ui_story_30850101_3_dialog_content = "<color=#e8d9bb>Jane sedang menyusun berkas-berkas. Tas kerja hitam yang selalu dia bawa ada di sampingnya, sedikit terbuka.</color>",
  ui_story_30850101_4_dialog_content = "<color=#e8d9bb>Berkas-berkas yang dimasukkan ke dalamnya digigit dan dirobek oleh kegelapan dari bagian tas kerja yang terbuka itu, seolah-olah berkas itu salah masuk ke lubang hitam.</color>",
  ui_story_30850101_5_dialog_content = "(Sepertinya ada berkas yang jatuh!)",
  ui_story_30850101_6_dialog_content = "Umbraton makin sering berurusan dengan Illumina belakangan ini. Ada banyak sekali informasi tentangnya...",
  ui_story_30850101_7_dialog_content = "(Jane sepertinya tidak menyadarinya, aku harus membantunya...)",
  ui_story_30850101_8_option_content = "Ambil berkas",
  ui_story_30850101_9_dialog_content = "Jane, berkasmu jatuh ke lantai, sebuah... wasiat.",
  ui_story_30850101_10_dialog_content = "Ditandatangani oleh Istvan...",
  ui_story_30850101_11_dialog_content = "Apa?! Wasiat Shadowlord?",
  ui_story_30850101_12_dialog_content = "Terima kasih, PlayerName. Pantas saja jumlahnya tidak pas.",
  ui_story_30850101_13_dialog_content = "Maaf, aku tidak bermaksud membaca berkasnya...",
  ui_story_30850101_14_dialog_content = "Jangan khawatir. Lagi pula ini bukan rahasia di Umbraton.",
  ui_story_30850101_15_dialog_content = "Ini sudah ada sejak Shadowlord mengambil posisinya.",
  ui_story_30850101_16_dialog_content = "Dia dan kematian saling menemani. Baginya, ajal tak bisa dihindari...",
  ui_story_30850101_17_dialog_content = "Bisa datang kapan pun.",
  ui_story_30850101_18_dialog_content = "<color=#FFFFFF>Wasiat Istvan</color>",
  ui_story_30850101_19_dialog_content = "<color=#FFFFFF>Hidupku bagaikan lilin yang tertiup angin. Aku hanya selangkah lagi dari kematian.</color>",
  ui_story_30850101_20_dialog_content = "<color=#FFFFFF>Saat bayangan tertidur, mata terpejam, tetapi tangan terentang.</color>",
  ui_story_30850101_21_dialog_content = "<color=#FFFFFF>Tubuh akan mati, tetapi kehendak tetap hidup.</color>",
  ui_story_30850101_22_dialog_content = "<color=#FFFFFF>Setelah aku meninggal, semua asetku akan disumbangkan ke panti asuhan;</color>",
  ui_story_30850101_X22_dialog_content = "<color=#FFFFFF>Aset dari Istvan Gang akan dikelola oleh Cloudrover Guild untuk menjaga ketertiban di Umbraton.</color>",
  ui_story_30850101_23_dialog_content = "Aku tak pernah mengira Shadowlord yang hebat itu bisa menjadi begitu pesimis tentang kehidupan...",
  ui_story_30850101_24_dialog_content = "Bukan, bukan pesimis melainkan realistis.",
  ui_story_30850101_25_dialog_content = "Hmm, menurutmu begitu? Aku tak menganggapmu sebagai seseorang yang akan berkomentar tentang orang lain.",
  ui_story_30850101_26_dialog_content = "...",
  ui_story_30850101_27_dialog_content = "Kamu benar, harusnya aku tak berkomentar. Sebagai <color=#FFB400>Witness</color>, aku hanya perlu bersaksi.",
  ui_story_30850101_28_dialog_content = "Tapi ketika aku berbicara denganmu, aku mengatakan apa yang ada di pikiranku tanpa sadar.",
  ui_story_30850101_29_dialog_content = "\"<color=#FFB400>Witness</color>\"?",
  ui_story_30850101_30_dialog_content = "Itu pekerjaanku.",
  ui_story_30850101_31_dialog_content = "Tanggung jawab utamaku adalah dengan tepat mencatat segala sesuatu yang terjadi.",
  ui_story_30850101_32_dialog_content = "Dari perubahan Faction dan pergantian astronomi hingga gosip dan kejadian sehari-hari.",
  ui_story_30850101_33_dialog_content = "<color=#FFB400>Aku menerima banyak informasi, tapi selalu berusaha untuk tetap tenang, rasional, dan objektif.</color>",
  ui_story_30850101_34_dialog_content = "Terkadang aku juga dibayar untuk membantu Sheol mencatat pinjaman dan transaksi Cloudrover Guild.",
  ui_story_30850101_35_dialog_content = "Itu bisnis sampinganku.",
  ui_story_30850101_36_dialog_content = "Kedengarannya rumit.",
  ui_story_30850101_37_dialog_content = "Intinya, aku mengumpulkan dan memproses informasi rahasia.",
  ui_story_30850101_38_dialog_content = "Jika ada sesuatu yang ingin kamu ketahui, aku bisa memberitahumu jika itu tidak berbahaya.",
  ui_story_30850101_39_dialog_content = "Mereka telah memberiku izin, jadi kamu tak perlu khawatir.",
  ui_story_30850101_40_option_content = "Beri tahu aku tinggi badan Vice",
  ui_story_30850101_41_dialog_content = "\"Vice, Co-Expedition Captain.\"",
  ui_story_30850101_42_dialog_content = "\"Lahir di Illumina Federation, Lieutenant.\"",
  ui_story_30850101_43_dialog_content = "\"Tingginya standar, 160 cm.\"",
  ui_story_30850101_44_dialog_content = "Omong-omong, Vice 10 kg lebih berat daripada Carleen, terutama karena dia memiliki ekor yang kuat.",
  ui_story_30850101_45_option_content = "Beri tahu aku kapan ulang tahun Carleen",
  ui_story_30850101_46_dialog_content = "\"Carleen, Kapten dari Guardian of Lumopolis Garden, putri kedua dari Lord of Lumopolis.\"",
  ui_story_30850101_47_dialog_content = "\"Tidak memihak dan jujur, dia membenci kejahatan dan dengan sepenuh hati percaya akan adanya keadilan mutlak.\"",
  ui_story_30850101_48_dialog_content = "\"Ulang tahunnya tanggal 31 Juli.\"",
  ui_story_30850101_49_dialog_content = "Omong-omong, tinggi Carleen 161 cm, 1 cm lebih tinggi dari Vice.",
  ui_story_30850101_50_option_content = "Beri tahu aku informasi tentang Jane",
  ui_story_30850101_51_dialog_content = "\"Jane, Witness Umbraton, netral dan objektif setiap saat.\"",
  ui_story_30850101_52_dialog_content = "\"Berpartner dengan Istvan, dan menjalin hubungan kerja dengan Sheol.\"",
  ui_story_30850101_53_dialog_content = "\"Jas dan tas kerja hitam adalah ciri khasnya.\"",
  ui_story_30850101_54_dialog_content = "Omong-omong, Chest of Mammon hanyalah peti biasa, berbeda dengan peti mati dan koper putih berisi monster.",
  ui_story_30850101_55_dialog_content = "... Siapa yang mengira PlayerName akan tertarik padaku, aku terkejut.",
  ui_story_30850101_56_dialog_content = "Ini hanya pertanyaan dengan jawaban singkat, tapi aku menerima terlalu banyak informasi.",
  ui_story_30850101_57_dialog_content = "Aku juga sudah mengumpulkan informasi rahasia tentang PlayerName.",
  ui_story_30850101_58_dialog_content = "\"Navigator Colossus - PlayerName. Ras: Caelestite.\"",
  ui_story_30850101_59_dialog_content = "\"Terlahir dengan keahlian bertempur yang buruk, tetapi mampu mengoperasikan Colossus dengan cara merasakan jalan terang.\"",
  ui_story_30850101_60_dialog_content = "\"Memiliki dunia batin yang kaya dan pandai memahami kontradiksi dan fokus dari berbagai hal.\"",
  ui_story_30850101_61_dialog_content = "\"Cenderung memaksakan diri, sering bekerja terlalu keras.\"",
  ui_story_30850101_62_dialog_content = "Oh, iya, kamu memiliki kebiasaan menulis di buku harian.",
  ui_story_30850101_63_dialog_content = "Ya.",
  ui_story_30850101_64_dialog_content = "Apakah memungkinkan bagiku untuk membaca buku harianmu?",
  ui_story_30850101_65_dialog_content = "Witness yang baik harus belajar dari catatan pengalaman orang lain.",
  ui_story_30850101_66_option_content = "Tentu saja",
  ui_story_30850101_67_dialog_content = "Ini adalah catatan pribadimu, tapi kamu menyetujui permintaanku.",
  ui_story_30850101_68_dialog_content = "PlayerName, kamu lebih baik dari yang aku kira.",
  ui_story_30850101_69_dialog_content = "Sebagai gantinya, aku akan menunjukkan buku harianku di lain waktu.",
  ui_story_30850101_70_option_content = "Itu agak...",
  ui_story_30850101_71_dialog_content = "Memalukan...",
  ui_story_30850101_72_dialog_content = "Tentu. Jika tidak membayarnya, permintaanku akan menjadi tuntutan yang kasar.",
  ui_story_30850101_73_dialog_content = "Aku juga akan berbagi buku harianku denganmu di kemudian hari.",
  ui_story_30850101_74_dialog_content = "*Menyerahkan buku harian kepada Jane*",
  ui_story_30850101_75_dialog_content = "... Ada beberapa catatan studi juga di situ.",
  ui_story_30850101_76_dialog_content = "Tampaknya, Navigator tidak berhenti belajar tentang dunia luar bahkan saat tinggal di dalam Colossus.",
  ui_story_30850101_77_dialog_content = "Pikiran pribadi ini... terkadang membingungkan, tapi sering kali penuh harapan.",
  ui_story_30850101_78_dialog_content = "Dan gaya tulisannya... mudah dibaca sembari menyampaikan gambaran yang jelas.",
  ui_story_30850101_79_dialog_content = "(Siapa yang menyangka Jane ternyata sangat pandai memuji? Sepertinya aku tersipu.)",
  ui_story_30850101_80_dialog_content = "Apakah ini komentarmu tentang semua orang?",
  ui_story_30850101_81_dialog_content = "\"<color=#FFB400>Connolly</color> adalah orang yang lembut dan kuat...\"",
  ui_story_30850101_82_dialog_content = "\"<color=#FFB400>Hydrad</color> terlihat menakutkan, tapi tindakannya selalu menghangatkan hati.\"",
  ui_story_30850101_83_dialog_content = "\"<color=#FFB400>Leona</color> sangat misterius, kuat, dan memiliki kepribadian yang unik...\"",
  ui_story_30850101_84_dialog_content = "\"<color=#FFB400>Jane...</color>\"",
  ui_story_30850101_85_dialog_content = "<color=#FFFFFF>\"terlihat agak menyendiri, sepertinya tidak mudah untuk didekati.\"</color>",
  ui_story_30850101_86_dialog_content = "...",
  ui_story_30850101_87_dialog_content = "Maaf, Jane. Bukan begitu yang kupikirkan...",
  ui_story_30850101_88_dialog_content = "Tak apa, Navigator.",
  ui_story_30850101_89_dialog_content = "Kamu hanya mencatat pikiranmu dengan tepat, yang harus dihormati. Ini tidak akan menyakitiku.",
  ui_story_30850101_90_dialog_content = "Selain itu, sejak aku memilih untuk menjadi Witness yang tenang dan rasional, aku sudah siap untuk menjaga jarak dari orang-orang.",
  ui_story_30850101_91_dialog_content = "Terima kasih atas bantuanmu. Sekian untuk hari ini.",
  ui_story_30850101_92_dialog_content = "Aku telah menyusun berkas-berkasku, kita akan berjumpa lagi.",
  ui_story_30850101_93_dialog_content = "Jane, tunggu...",
  ui_story_30850101_94_dialog_content = "<color=#e8d9bb>Sebuah catatan kecil jatuh dari buku harian.</color>",
  ui_story_30850101_95_dialog_content = "Maaf, ini catatanmu. Ini...",
  ui_story_30850101_96_dialog_content = "<color=#FFFFFF>\"Dia terlihat seperti tidak mudah untuk didekati, tapi Jane benar-benar membantuku.\"</color>",
  ui_story_30850101_A1_dialog_content = "<color=#FFFFFF>\"Dia terlihat kuat dari luar, tapi hatinya lembut. Semoga kami bisa berteman suatu saat nanti.\"</color>",
  ui_story_30850101_97_dialog_content = "PlayerName?",
  ui_story_30850101_98_dialog_content = "Sebenarnya, aku ingin berterima kasih atas apa yang terjadi saat Colossus mengalami pemadaman.",
  ui_story_30850101_99_dialog_content = "Soroz kehabisan daya, dan Colossus tiba-tiba terjerumus ke dalam kegelapan...",
  ui_story_30850101_100_dialog_content = "Tapi aku tidak segera memperbaiki Colossus.",
  ui_story_30850101_101_dialog_content = "Benar. Catatanku tertulis, \"Colossus mengalami pemadaman, Navigator gugup.\"",
  ui_story_30850101_102_dialog_content = "Aku sendirian di kamarku, merasa sedikit tertekan, ragu-ragu, dan kesepian.",
  ui_story_30850101_103_dialog_content = "Aku tak tahu kenapa aku merasa seperti itu.",
  ui_story_30850101_104_dialog_content = "Mungkin aku menyadari bahwa tak mudah meninggalkan tempat yang selalu aku tinggali.",
  ui_story_30850101_105_dialog_content = "Terkadang, semua orang merasa seperti itu.",
  ui_story_30850101_106_dialog_content = "Tapi, entah bagaimana, botol Hydrad menggelinding masuk ke kamarku.",
  ui_story_30850101_107_dialog_content = "Botol biru yang memancarkan cahaya redup itu membuatku merasa lebih baik.",
  ui_story_30850101_108_dialog_content = "Hydrad dan Shadow Wolf yang berisik muncul setelahnya, langsung membangkitkan semangatku.",
  ui_story_30850101_109_dialog_content = "\"Hydrad, penyendiri yang baik.\" Sebenarnya, dia sangat cerdik dan pandai merasakan suasana.",
  ui_story_30850101_110_dialog_content = "Tidak hanya Hydrad, kamu juga begitu.",
  ui_story_30850101_111_dialog_content = "...",
  ui_story_30850101_112_dialog_content = "Mampu mengamati segala sesuatu yang terjadi di sekitarmu, bahkan perbedaan sekecil apa pun, lalu diam-diam mengulurkan tangan untuk membantu.",
  ui_story_30850101_113_dialog_content = "Jane yang melempar botol Hydrad ke kamarku untuk memancingnya ke sana, 'kan?",
  ui_story_30850101_114_dialog_content = "Apakah PlayerName melihatku?",
  ui_story_30850101_115_dialog_content = "Aku tahu. Aku bukan Witness satu-satunya. Semua orang di sekitarku juga adalah Witness...",
  ui_story_30850101_116_dialog_content = "Sepertinya aku sudah memahami dengan lebih baik tentang siapa aku sekarang.",
  ui_story_30850101_117_dialog_content = "Terima kasih, PlayerName.",
  ui_story_30850101_118_dialog_content = "Aku boleh membawa catatan ini? Ini... sangat penting bagiku.",
  ui_story_30850101_119_dialog_content = "Tentu.",
  ui_story_30850101_120_dialog_content = "Aku tahu apa yang kamu inginkan sekarang. Witness akan mencatatnya.",
  ui_story_30850101_121_dialog_content = "Kalau begitu, sampai jumpa di lain waktu, PlayerName.",
  ui_story_30850101_122_dialog_content = "<color=#e8d9bb>Jane sudah akan pergi, tetapi berkas lain jatuh dari tas kerja hitamnya.</color>",
  ui_story_30850101_123_dialog_content = "Jane, tunggu! Kamu menjatuhkan sesuatu!",
  ui_story_30850101_124_dialog_content = "Ada terlalu banyak berkas. Chest of Mammon tidak mampu menampung semuanya.",
  ui_story_30850101_125_dialog_content = "Ah, ini. Wasiat Lord of Lumopolis.",
  ui_story_30850101_126_dialog_content = "Apa Lord of Lumopolis juga menulis wasiat?",
  ui_story_30850101_127_dialog_content = "Tidak, aku tidak bisa mendapatkan wasiatnya, tentu saja.",
  ui_story_30850101_128_dialog_content = "Shadowlord yang menulis ini. Dia pasti mengerjaiku.",
  ui_story_30850101_129_dialog_content = "Shadowlord memiliki... sisi yang menyenangkan? Aku mendapat banyak kejutan hari ini.",
  ui_story_30850101_130_dialog_content = "Aku akan memberitahumu informasi rahasia yang lain.",
  ui_story_30850101_131_dialog_content = "Lord of Lumopolis sebenarnya lebih muda dari Shadowlord, dan dia adalah pria tampan tanpa janggut.",
  ui_story_30850101_132_dialog_content = "Dia terlihat seperti ini... kamu lihat?",
  ui_story_30850101_133_dialog_content = "Hah?!",
  ui_story_30850101_134_dialog_content = "Aku juga terkejut saat mengetahuinya.",
  ui_story_30850101_135_dialog_content = "Tapi hanya sedikit terkejut. Lagi pula, aku ini Witness yang profesional.",
  ui_story_30850101_136_dialog_content = "Informasimu terlalu banyak. Biarkan aku mencernanya dengan perlahan...",
  ui_story_30850101_137_dialog_content = "Sepertinya tak mudah menjadi Witness yang netral.",
  ui_story_30850601_1_dialog_content = "Alkisah... Ada negeri yang aneh dan misterius.",
  ui_story_30850601_2_dialog_content = "Malam gelap gulita dan awan suram menyelimuti langit. Bahkan secercah cahaya bintang pun tidak terlihat di atas.",
  ui_story_30850601_3_dialog_content = "Suatu malam, negeri itu dingin dan tenang seperti biasanya, satu-satunya suara yang terdengar adalah gemerisik dedaunan yang tertiup angin.",
  ui_story_30850601_4_dialog_content = "Tiba-tiba, terdengar suara keras dan gaduh!",
  ui_story_30850601_5_dialog_content = "Sst... Kamu dengar itu?",
  ui_story_30850601_6_dialog_content = "A-aku tidak dengar apa-apa...",
  ui_story_30850601_7_dialog_content = "Buk-Buk-Buk... Buk-Buk-Buk! Suara hentakan yang tersebar merobek kesunyian malam.",
  ui_story_30850601_8_dialog_content = "Kemudian, secercah cahaya bintang terkecil bersinar dari langit, mengungkapkan asal suara itu!",
  ui_story_30850601_9_dialog_content = "Gedebuk-gedebuk! Gedebuk-gedebuk! Dulu... <color=#FFB400>Hantu</color>!",
  ui_story_30850601_10_dialog_content = "Hantu macam apa?",
  ui_story_30850601_11_dialog_content = "Hantu menyeramkan, dengan tiga kepala, enam tangan, dan sembilan kaki!",
  ui_story_30850601_12_dialog_content = "Apa? Itu tidak terlalu menarik...",
  ui_story_30850601_13_dialog_content = "...Hantu itu tertidur dalam kegelapan, rasa laparnya perlahan-lahan menjadi tak terkendali.",
  ui_story_30850601_14_dialog_content = "Matanya melongo, dilirik dan mengintip, mencari sesuatu untuk mengisi perutnya yang keroncongan...",
  ui_story_30850601_15_dialog_content = "Hantu itu berpikir, \"Kalau saja ada anak nakal di dekat sini! Kudengar rasanya yang paling enak!\"",
  ui_story_30850601_16_dialog_content = "Aku tidak nakal!",
  ui_story_30850601_17_dialog_content = "Ya, aku juga tidak!",
  ui_story_30850601_18_dialog_content = "Tiba-tiba, setelah mendengar suara gemerisik samar di dekatnya, hantu itu menyambar seekor kelinci dari tanah!",
  ui_story_30850601_19_dialog_content = "Mata menakutkan hantu itu menatap mata * bip * kelinci.",
  ui_story_30850601_20_dialog_content = "Masing-masing dari tiga kepala hantu itu ingin memakan kelinci itu.",
  ui_story_30850601_21_dialog_content = "Dengan telapak tangannya mem-*biip* bersama, kepalan tangan hantu lainnya mulai mem-*biip* kepalanya sendiri.",
  ui_story_30850601_22_dialog_content = "Eh... Kenapa kamu terus berkata biip?",
  ui_story_30850601_23_dialog_content = "Versi kisah yang diceritakan kepadaku penuh dengan kata biip... Gunakan saja imajinasimu untuk mengisi kata yang kosong itu.",
  ui_story_30850601_24_dialog_content = "Kami tidak ingin mendengar biip! Kami ingin mendengar cerita lengkapnya!",
  ui_story_30850601_25_dialog_content = "(Tapi ini cerita lengkapnya... Setidaknya, begitulah Soroz menceritakannya...)",
  ui_story_30850601_26_dialog_content = "(Sepertinya mereka tidak akan suka jika aku terus mengatakannya seperti ini. Aku harus membuat beberapa perubahan...)",
  ui_story_30850601_27_dialog_content = "A-Ahem... Jadi, seperti yang kubilang, banyak tangan dan kaki hantu itu mulai berkelahi satu sama lain.",
  ui_story_30850601_28_dialog_content = "Jadi, siapa yang menang? Ceritakan!",
  ui_story_30850601_29_dialog_content = "Tak satu pun dari kepala hantu itu membiarkan yang lain menang. Kepala pertama menggigit lengan ketiga, menolak untuk melepaskannya.",
  ui_story_30850601_30_dialog_content = "Kaki keenam menendang keras kepala ketiga, dan tangan kelima mencakar kaki kedua.",
  ui_story_30850601_31_dialog_content = "Lalu...",
  ui_story_30850601_32_dialog_content = "Apa yang terjadi?!",
  ui_story_30850601_33_dialog_content = "Kelinci itu menemukan kesempatan untuk kabur!",
  ui_story_30850601_34_dialog_content = "Lalu? Setelah itu bagaimana?!",
  ui_story_30850601_35_dialog_content = "T-tidak ada apa-apa! Itulah akhir ceritaku...!",
  ui_story_30850601_36_dialog_content = "Jadi, pelajaran dari cerita ini...",
  ui_story_30850601_37_dialog_content = "Tapi, bagaimana kelinci itu bisa kabur?",
  ui_story_30850601_38_dialog_content = "Eh... Yah...",
  ui_story_30850601_39_dialog_content = "Lalu, bagaimana nasib hantu itu setelahnya?",
  ui_story_30850601_40_dialog_content = "E-eh... Hmm...",
  ui_story_30850601_41_dialog_content = "(Apa yang harus saya lakukan? Saya tidak bisa mengatakan kepada mereka bahwa saya tidak tahu...)",
  ui_story_30850601_42_dialog_content = "*Berdesah*",
  ui_story_30850601_43_dialog_content = "Cerita hantu ini payah.",
  ui_story_30850601_44_dialog_content = "Ya! Bahkan saya bisa menceritakan kisah yang lebih baik!",
  ui_story_30850601_45_dialog_content = "Kau benar-benar mengagumkan, PlayerName.",
  ui_story_30850601_46_dialog_content = "Sungguh? Sepertinya hanya kau satu-satunya yang menyukai ceritaku...",
  ui_story_30850601_47_dialog_content = "Maksudku, kau membuatku ragu untuk pertama kalinya sepanjang karirku...",
  ui_story_30850601_48_dialog_content = "Tentang apakah saya ingin menuliskan cerita yang saya dengar.",
  ui_story_30850601_49_dialog_content = "(Jane... Bahkan kamu...)",
  ui_story_30850601_50_dialog_content = "(Bagaimana tadi awalnya aku bisa bercerita di sini...?)",
  ui_story_30850601_51_dialog_content = "(Saya datang ke Umbraton untuk mendapatkan beberapa perbekalan dan bertemu Jane.)",
  ui_story_30850601_52_dialog_content = "(Saat itulah aku mendengar suara anak-anak berteriak dari panti asuhan...)",
  ui_story_30850601_53_dialog_content = "(Ternyata mereka saling menceritakan kisah hantu.)",
  ui_story_30850601_54_dialog_content = "(Saya ingat cerita Soroz sejak saya masih kecil, jadi saya berjanji untuk membagikannya kepada anak-anak.)",
  ui_story_30850601_55_dialog_content = "(Saya tidak pernah berpikir akan menjadi seperti ini...)",
  ui_story_30850601_56_dialog_content = "Cerita itu mengerikan. Bisakah Anda memberi tahu kami yang lebih baik?",
  ui_story_30850601_57_dialog_content = "Maaf, anak-anak. Aku tidak bisa menceritakan kisah hantu.",
  ui_story_30850601_58_dialog_content = "Tapi, sebagai saksi, aku bisa menceritakan kepada kalian segala hal yang pernah kulihat sendiri.",
  ui_story_30850601_59_dialog_content = "Beberapa dari mereka terdengar sulit dipercaya tetapi benar. Yang lain terdengar nyata tetapi akhirnya tidak lebih dari dongeng.",
  ui_story_30850601_60_dialog_content = "Salah satu dari kisah itu bahkan menceritakan tentang <color=#FFB400>Phantom</color>.",
  ui_story_30850601_61_dialog_content = "Wow! Cerita ini terdengar jauh lebih keren!",
  ui_story_30850601_62_dialog_content = "(Mengapa mereka semua menoleh ke arahku? ...Dan mengapa mereka menatapku seolah-olah aku baru saja menyinggung perasaan mereka?!)",
  ui_story_30850601_63_dialog_content = "Dahulu kala, ada seorang Aurorian, sama seperti kita, yang tinggal di negeri yang sama ini.",
  ui_story_30850601_64_dialog_content = "Aurorian memiliki seorang istri yang cantik, dan dua anak yang menggemaskan.",
  ui_story_30850601_65_dialog_content = "Namun suatu hari, seseorang menculik anak-anak Aurorian tanpa jejak.",
  ui_story_30850601_66_dialog_content = "Sang istri, yang menyalahkan dirinya sendiri, segera jatuh sakit dan meninggal dunia, dan sang suami sangat terpukul oleh tragedi demi tragedi.",
  ui_story_30850601_67_dialog_content = "Dia mulai mengenakan gaun tua istrinya dan bepergian melintasi negeri...",
  ui_story_30850601_68_dialog_content = "Dia akan bertanya kepada siapa pun yang dia temui dengan pertanyaan yang sama: \"Apa kau melihat anak-anakku?\"",
  ui_story_30850601_69_dialog_content = "Dan setiap kali dia bertemu dengan seorang anak... Dia akan menarik mereka ke sisinya, sambil menangis, \"Ini anakku!\"",
  ui_story_30850601_70_dialog_content = "Orang-orang segera belajar untuk menghindari pria Aurorian itu, dan akhirnya, dia menghilang.",
  ui_story_30850601_71_dialog_content = "Ada yang bilang dia menjadi Phantom yang menyeramkan, bersembunyi di tempat-tempat yang tidak bisa dilihat orang lain.",
  ui_story_30850601_72_dialog_content = "Dia menunggu waktunya, menunggu anak-anak yang kesepian dan tidak curiga mendekat, dan ketika mereka melakukannya... Dia membawa mereka pergi ke tempat yang gelap dan suram, tempat malam abadi.",
  ui_story_30850601_73_dialog_content = "Mereka mengatakan bahwa bahkan hari ini, dia bersembunyi di sudut tergelap tanah, diam-diam mengawasi semua orang...",
  ui_story_30850601_74_dialog_content = "Dan siapa tahu, dia bahkan mungkin ada...",
  ui_story_30850601_75_dialog_content = "Tepat di belakangmu!",
  ui_story_30850601_76_dialog_content = "Aaaaaaaaaaaah!!!!",
  ui_story_30850601_77_dialog_content = "Jangan biarkan dia menangkapku!",
  ui_story_30850601_78_dialog_content = "Aku tidak mau pergi ke tempat yang gelap!",
  ui_story_30850601_79_dialog_content = "Tenang! Itu hanya sebuah cerita! Tidak ada yang akan menculikmu!",
  ui_story_30850601_80_dialog_content = "......",
  ui_story_30850601_81_dialog_content = "(Mengapa gadis itu duduk jauh dari orang lain?)",
  ui_story_30850601_82_dialog_content = "Hai, apa kamu baik-baik saja?",
  ui_story_30850601_83_dialog_content = "Apakah Anda benar-benar berpikir malam abadi tidak bisa dihindari?",
  ui_story_30850601_84_dialog_content = "A-aku tak bisa menjawabnya dengan pasti, tapi menurutku tidak akan ada yang bisa bertahan lama di sana...",
  ui_story_30850601_85_dialog_content = "Lalu... apakah Anda tahu ke mana orang pergi ketika mereka mati?",
  ui_story_30850601_86_dialog_content = "Hmm... Intinya, mereka berubah menjadi bintang-bintang setelah meninggal.",
  ui_story_30850601_87_dialog_content = "Bisa jadi mereka berada di langit sekarang, mengawasi kita semua.",
  ui_story_30850601_88_dialog_content = "Itu adalah kebohongan yang sering dikatakan orang dewasa kepada anak-anak. Saya tidak percaya sama sekali.",
  ui_story_30850601_89_dialog_content = "Tahu tidak? Kudengar saat orang-orang meninggal, jiwa-jiwa mereka pergi ke negeri malam yang abadi...",
  ui_story_30850601_90_dialog_content = "Orang-orang hidup tak bisa pergi ke sana, dan orang-orang yang sudah mati tidak bisa meninggalkan tempat itu.",
  ui_story_30850601_91_dialog_content = "Saya belum pernah mendengar tentang legenda ini sampai sekarang.",
  ui_story_30850601_92_dialog_content = "Itu sebabnya... Saya sangat berharap hantu itu nyata.",
  ui_story_30850601_94_dialog_content = "Phantom itu bisa datang dan pergi dari malam yang abadi, tempat orang tuaku berada sekarang.",
  ui_story_30850601_95_dialog_content = "Jika mereka berada di tempat yang sama, bisa jadi Phantom itu pernah melihat orang tuaku.",
  ui_story_30850601_96_dialog_content = "Bisa jadi mereka bertetangga!",
  ui_story_30850601_97_dialog_content = "Saya ingin bertemu hantu itu, jika dia ada!",
  ui_story_30850601_98_dialog_content = "Aku bisa bertanya kepadanya apakah dia mengenal orang tuaku, dan apakah mereka baik-baik saja.",
  ui_story_30850601_99_dialog_content = "Meminta Phantom untuk mengirimkan pesanmu kepada orang tuamu yang telah meninggal...",
  ui_story_30850601_100_dialog_content = "Aku merindukan ibu dan ayahku...",
  ui_story_30850601_101_dialog_content = "Aku juga merindukan mereka...",
  ui_story_30850601_102_dialog_content = "Ayah... Ibu...",
  ui_story_30850601_103_dialog_content = "Aku... Aku ingin tahu bagaimana keadaan mereka sekarang...",
  ui_story_30850601_104_dialog_content = "...Tunggu dulu, ceritanya belum berakhir.",
  ui_story_30850601_105_dialog_content = "Konon, jika kalian mengucapkan namanya diam-diam <color=#FFB400>dua belas kali</color> pada <color=#FFB400>tengah malam</color>, Phantom akan muncul.",
  ui_story_30850601_106_dialog_content = "Jika Anda cukup berani untuk melakukannya, Anda mungkin dapat mengajukan pertanyaan kepadanya.",
  ui_story_30850601_107_dialog_content = "Aku 'kan pemberani! Aku akan melakukannya!",
  ui_story_30850601_108_dialog_content = "Aku ikut!",
  ui_story_30850601_109_dialog_content = "Aku juga, aku juga!",
  ui_story_30850601_110_dialog_content = "Hei, Jane? Bagian terakhir cerita itu...",
  ui_story_30850601_111_option_content = "Itu tidak sungguhan, 'kan?",
  ui_story_30850601_112_dialog_content = "Aku hanya seorang saksi. Aku tak tahu pasti mana yang sungguhan dan mana yang bohongan.",
  ui_story_30850601_113_option_content = "Kau baru saja mengarangnya, 'kan?",
  ui_story_30850601_114_dialog_content = "Saya hanya saksi. Saya tidak mengada-ada tentang cerita-cerita itu.",
  ui_story_30850601_115_dialog_content = "Oh, benar. Aku baru saja mendapat pesan dari Shadowlord. Aku punya beberapa hal untuk dihadiri.",
  ui_story_30850601_116_dialog_content = "Tapi aku berjanji pada guru di panti asuhan bahwa aku akan menggantikannya di kelas hari ini.",
  ui_story_30850601_117_dialog_content = "Karena itu, aku menitipkan mereka semua kepadamu, PlayerName.",
  ui_story_30850601_118_dialog_content = "Apa?",
  ui_story_30850601_119_dialog_content = "Aku tidak pernah mengurus anak-anak sebelumnya! Apakah itu benar-benar baik-baik saja?",
  ui_story_30850601_120_dialog_content = "Tentu saja! Kami akan mengajarkan caranya padamu!",
  ui_story_30850601_121_dialog_content = "Ya, jangan khawatir! Kami akan mengurusmu dengan baik!",
  ui_story_30850601_122_dialog_content = "Kau berada di tangan yang tepat!",
  ui_story_30850601_123_dialog_content = "Kenapa aku malah menjadi anak yang perlu diasuh...?",
  ui_story_30850601_124_dialog_content = "<color=#e8d9bb>Malam itu, pada tengah malam...</color>",
  ui_story_30850601_125_dialog_content = "Phantom, Phantom, Phantom, Phantom...",
  ui_story_30850601_126_dialog_content = "<color=#e8d9bb>Wuuss...</color>",
  ui_story_30850601_127_dialog_content = "I-itu hanya angin...",
  ui_story_30850601_128_dialog_content = "Mungkin Phantom sedang dalam perjalanan? Ayo panggil terus!",
  ui_story_30850601_129_dialog_content = "Phantom... Phantom...",
  ui_story_30850601_130_dialog_content = "<color=#e8d9bb>Kring-kring... Huu...</color>",
  ui_story_30850601_131_dialog_content = "Sudah dua belas kali... Kenapa Phantom itu tidak datang, sih?",
  ui_story_30850601_132_dialog_content = "(Bagaimana aku bisa menghibur mereka dalam situasi seperti ini...?)",
  ui_story_30850601_133_dialog_content = "<color=#e8d9bb>Krieeek...</color>",
  ui_story_30850601_134_dialog_content = "Tunggu, bukankah aku mengunci pintunya?",
  ui_story_30850601_135_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_30850601_136_dialog_content = "Brrr... D-dingin sekali...",
  ui_story_30850601_137_dialog_content = "Lihat! Ada sesuatu yang baru saja terbang!",
  ui_story_30850601_138_dialog_content = "Lihat! Kelopak bunga! Kelopak ungu...!",
  ui_story_30850601_139_dialog_content = "Saat jam berdentang dua belas, garis antara malam abadi dan alam fana menjadi kabur. Demikianlah jembatan takdir membawaku ke sini hari ini...",
  ui_story_30850601_140_dialog_content = "Aku seorang pengelana yang tak kenal lelah dalam kegelapan, seorang utusan yang menanggung beban pikiran-pikiran dari orang lain.",
  ui_story_30850601_141_dialog_content = "Saat lonceng berdentang dua belas kali, aku mendengar namaku diucapkan oleh orang yang lemah lembut dua belas kali juga.",
  ui_story_30850601_142_dialog_content = "Sekarang, biarkan kelopak-kelopak bunga unguku ini berhamburan selagi aku melihat wajah pemanggilku.",
  ui_story_30850601_143_dialog_content = "Itu Phantom-nya!",
  ui_story_30850601_144_dialog_content = "Aaaaaaaaaaah!!!",
  ui_story_30850601_145_dialog_content = "Apakah kalian yang memanggilku malam ini, anak-anak?",
  ui_story_30850601_146_dialog_content = "*Menangis* B-bukan aku!",
  ui_story_30850601_147_dialog_content = "Bukan aku juga!",
  ui_story_30850601_148_dialog_content = "Oh. Aku penasaran...",
  ui_story_30850601_149_dialog_content = "Tetangga saya mempercayakan saya dengan banyak kenang-kenangan yang tak terlupakan...",
  ui_story_30850601_150_dialog_content = "Meminta saya untuk mengikuti suara-suara yang memanggil saya, agar saya dapat meneruskan hal-hal ini kepada anak-anak mereka.",
  ui_story_30850601_151_dialog_content = "Apa mungkin mereka salah? Jika iya, aku harus segera pergi...",
  ui_story_30850601_152_dialog_content = "T-tunggu! Kenang-kenangan itu... Sebenarnya apa?",
  ui_story_30850601_153_dialog_content = "Itu adalah apa yang Anda lihat di hadapan Anda sekarang, kelopak bunga ungu yang indah di tangan saya.",
  ui_story_30850601_154_dialog_content = "Bunga-bunga ini tumbuh dengan berisikan pesan dari tetangga-tetanggaku.",
  ui_story_30850601_155_dialog_content = "Selama anak-anak mereka berbicara kepada kelopak-kelopak bunga ini, suara mereka akan disampaikan kembali ke negeri malam yang abadi, tempat mereka bisa mendengar setiap kata.",
  ui_story_30850601_156_dialog_content = "A-apakah ada satu untukku? Akulah yang memanggil namamu dua belas kali, Tuan Phantom, dan tidak kurang satu kali pun!",
  ui_story_30850601_157_dialog_content = "Benarkah itu? Biar kulihat... Ah, ya. Yang ini khusus untukmu. Ambillah.",
  ui_story_30850601_158_dialog_content = "Terima kasih, Tuan Phantom!",
  ui_story_30850601_159_dialog_content = "Ayah? Ibu? Jangan mencemaskan aku... Aku baik-baik saja!",
  ui_story_30850601_160_dialog_content = "......",
  ui_story_30850601_161_dialog_content = "A-aku juga ingin berbicara kepada orang tuaku!",
  ui_story_30850601_162_dialog_content = "Y-ya, aku juga!",
  ui_story_30850601_163_dialog_content = "Di mana bungaku?",
  ui_story_30850601_164_dialog_content = "Ada bunga untuk semua orang, asalkan Anda menyebut nama saya dua belas kali.",
  ui_story_30850601_165_dialog_content = "Terima kasih, Tuan Phantom!",
  ui_story_30850601_166_dialog_content = "Hmm? Satu bunga tambahan?",
  ui_story_30850601_167_dialog_content = "Ah, ini pasti milikmu.",
  ui_story_30850601_168_dialog_content = "M-milikku?",
  ui_story_30850601_169_dialog_content = "Ekspresimu aneh sekali. Tentu saja bunga ini adalah untukmu.",
  ui_story_30850601_170_dialog_content = "...Terima kasih.",
  ui_story_30850601_171_dialog_content = "Tunggu... Bukankah kau...?!",
  ui_story_30850601_172_dialog_content = "<size=30>Sst! Jangan beri tahu anak-anak itu!</size>",
  ui_story_30850601_173_dialog_content = "Ahem! Aku memang hantu. May Aku menolongmu?",
  ui_story_30850601_174_dialog_content = "T-Sudahlah, terima kasih. Anda hanya terlihat sedikit berbeda dari apa yang saya bayangkan ...",
  ui_story_30850601_175_dialog_content = "Sungguh kasihan... Wujudku persis seperti yang seharusnya.",
  ui_story_30850601_176_dialog_content = "Bunga kerinduan ini, penuh dengan kata-kata baikmu, sudah mulai mekar di rumah mereka, anak-anak.",
  ui_story_30850601_177_dialog_content = "Sekarang, aku harus meninggalkan tempat ini sebelum lonceng berdentang sekali lagi.",
  ui_story_30850601_178_dialog_content = "Tak perlu perpisahan yang panjang karena kita semua akan bertemu lagi suatu saat nanti... Di negeri malam yang abadi.",
  ui_story_30850601_179_dialog_content = "K-ke mana Phantom itu pergi?!",
  ui_story_30850601_180_dialog_content = "Ah... Aku tidak sempat berterima kasih padanya.",
  ui_story_30850601_181_dialog_content = "......",
  ui_story_30850601_182_dialog_content = "Rambut putih pendek, dengan dua tanduk hitam runcing...",
  ui_story_30850601_183_dialog_content = "Meskipun dia mengganti pakaiannya, dan kehadiran aneh itu memang benar... Tapi apakah anak-anak benar-benar tidak mengenalinya?",
  ui_story_30850601_184_dialog_content = "Apa yang kamu gumamkan?",
  ui_story_30850601_185_dialog_content = "H-hah? Oh, tidak apa-apa...",
  ui_story_30850601_186_dialog_content = "Tadi itu wanita yang kemari hari ini, 'kan?",
  ui_story_30850601_187_dialog_content = "Anda melihatnya, bukan?",
  ui_story_30850601_188_dialog_content = "Tapi, tetap saja dia adalah Phantom.",
  ui_story_30850601_189_dialog_content = "Apa maksudmu?",
  ui_story_30850601_190_dialog_content = "Mengirim pesan ke orang mati hanyalah kebohongan besar.",
  ui_story_30850601_191_dialog_content = "Sama seperti Phantom dalam cerita itu dan juga bunga-bunga ungu ini.",
  ui_story_30850601_192_dialog_content = "Tapi... Bunga-bunga ini cantik, 'kan?",
  ui_story_30850601_193_dialog_content = "(Ada apa ini? Aku hampir tidak bisa mengerti apa yang dimaksud anak itu...)",
  ui_story_30850601_194_dialog_content = "Ehem, omong-omong... Kau tidak akan memberi tahu ini kepada anak-anak lain, 'kan?",
  ui_story_30850601_195_dialog_content = "Aku tak akan pernah memberi tahu mereka. Aku akan menyimpan rahasia yang manis dan indah ini di dalam hatiku.",
  ui_story_30850601_196_dialog_content = "Hai...? Bisa tolong katakan padanya terima kasih... untukku?",
  ui_story_30850601_197_dialog_content = "Tentu saja! Aku pasti akan menyampaikannya!",
  ui_story_30850601_198_dialog_content = "Ini akan menjadi rahasia kecil kita!",
  ui_story_30850601_199_dialog_content = "Baik!",
  ui_story_30850601_200_dialog_content = "<color=#e8d9bb>Wuuss...</color>",
  ui_story_30850601_201_dialog_content = "Ah... Bungaku tertiup angin...",
  ui_story_30850601_202_dialog_content = "Jangan khawatir, aku akan mengambilnya.",
  ui_story_30850601_203_dialog_content = "Bungamu sangat spesial, tahu tidak? Ini.",
  ui_story_30850601_204_dialog_content = "Hmm? Kemana dia pergi?",
  ui_story_30850601_205_dialog_content = "Mengapa bunga Anda berbeda dari kami?",
  ui_story_30850601_206_dialog_content = "Hei anak-anak, apakah kalian melihat ke mana gadis kecil itu pergi tadi?",
  ui_story_30850601_207_dialog_content = "Gadis kecil yang mana? Kami semua ada di sini!",
  ui_story_30850601_208_dialog_content = "Lihat, bungaku lebih besar dari punyamu!",
  ui_story_30850601_209_dialog_content = "Mana mungkin!",
  ui_story_30850601_210_dialog_content = "Hahahaha!",
  ui_story_30850601_211_dialog_content = "Apakah mungkin... Phantom itu benar-benar ada?",
  ui_story_30850601_212_dialog_content = "Yah, bahkan jika ada satu ...",
  ui_story_30850601_213_dialog_content = "Mungkin itu yang kita sebut... Harapan."
}
return config
